/**
 * @jest-environment node
 *
 * The real pdf-lib needs to read the generated bytes back, which fails under
 * jsdom's foreign-realm Uint8Array, so this suite runs in the node environment.
 */
import { PDFDocument, PDFDict, PDFName, PDFRawStream } from 'pdf-lib';
import zlib from 'zlib';
import {
  buildExportFileName,
  formatPrice,
  generateProductsPdf,
  ROWS_PER_PAGE,
  type PdfMeta,
  type ProductRow,
} from './pdf';

const makeRows = (n: number): ProductRow[] =>
  Array.from({ length: n }, (_, i) => ({
    code: `P${String(i).padStart(3, '0')}`,
    name: `Producto ${i}`,
    stock: i,
    price: 1000 + i,
  }));

const META: PdfMeta = {
  branchName: 'Sucursal Depósito',
  branchCode: 'DEP',
  date: new Date(2026, 7, 6, 15, 30),
};

const loadPdf = (base64: string) => PDFDocument.load(Buffer.from(base64, 'base64'));

// pdf-lib writes every page's content stream deflated, and non-ASCII text as hex
// strings, so the only way to read the printed text back is to inflate the
// streams and decode those hex strings.
const pdfText = (base64: string): string => {
  const buf = Buffer.from(base64, 'base64');
  const raw = buf.toString('latin1');
  const deflated: string[] = [];
  const streamStart = /stream\r?\n/g;
  let match: RegExpExecArray | null;
  while ((match = streamStart.exec(raw)) !== null) {
    const start = match.index + match[0].length;
    const end = raw.indexOf('endstream', start);
    if (end < 0) continue;
    try {
      deflated.push(zlib.inflateSync(buf.subarray(start, end)).toString('latin1'));
    } catch {
      // Streams stored without compression carry no text content.
    }
  }
  return deflated
    .join('\n')
    .replace(/<([0-9A-Fa-f]+)>/g, (_all, hex: string) => Buffer.from(hex, 'hex').toString('latin1'));
};

const imageXObjects = (pdfDoc: PDFDocument, pageIndex = 0): PDFRawStream[] => {
  const resources = pdfDoc.getPages()[pageIndex].node.Resources();
  const xobjects = resources?.lookup(PDFName.of('XObject'), PDFDict);
  if (!xobjects) return [];
  return [...xobjects.entries()]
    .map(([, ref]) => pdfDoc.context.lookup(ref))
    .filter(
      (value): value is PDFRawStream =>
        value instanceof PDFRawStream &&
        String(value.dict.get(PDFName.of('Subtype'))) === '/Image'
    );
};

describe('generateProductsPdf', () => {
  test('renders a valid single-page PDF for a small selection', async () => {
    const base64 = await generateProductsPdf(makeRows(5), META);

    const pdfDoc = await loadPdf(base64);
    expect(pdfDoc.getPageCount()).toBe(1);
  });

  test('overflows to a new page without truncation and stays valid', async () => {
    const base64 = await generateProductsPdf(makeRows(80), META);

    const pdfDoc = await loadPdf(base64);
    expect(pdfDoc.getPageCount()).toBe(3);
  });

  test('spills to a second page right past the recomputed row capacity', async () => {
    const base64 = await generateProductsPdf(makeRows(33), META);

    const pdfDoc = await loadPdf(base64);
    expect(pdfDoc.getPageCount()).toBe(2);
  });

  test('an empty selection still produces a valid one-page PDF', async () => {
    const base64 = await generateProductsPdf([], META);

    const pdfDoc = await loadPdf(base64);
    expect(pdfDoc.getPageCount()).toBe(1);
  });

  test('embeds the store logo as an image on the page', async () => {
    const pdfDoc = await loadPdf(await generateProductsPdf(makeRows(3), META));

    expect(imageXObjects(pdfDoc)).toHaveLength(1);
  });

  test('prints the branch name and the export date in the header', async () => {
    const text = pdfText(await generateProductsPdf(makeRows(3), META));

    expect(text).toContain('Sucursal Depósito');
    expect(text).toContain('DEP');
    expect(text).toContain('06/08/2026');
  });

  test('prints the selected product count and their total units', async () => {
    const text = pdfText(await generateProductsPdf(makeRows(33), META));

    // makeRows() gives stock 0..32, so the 33 rows add up to 528 units.
    expect(text).toContain('33 productos');
    expect(text).toContain('528 unidades');
  });

  test('numbers every page of a multi-page export', async () => {
    const text = pdfText(await generateProductsPdf(makeRows(80), META));

    expect(text).toContain('Página 1 de 3');
    expect(text).toContain('Página 3 de 3');
  });
});

describe('ROWS_PER_PAGE', () => {
  test('accounts for the taller header band plus the reserved totals line', () => {
    // 841.89 - 2*36 margin - 56 band - 14 gap - 20 titles - 22 totals = 657.89
    // floor(657.89 / 20) = 32 rows per page.
    expect(ROWS_PER_PAGE).toBe(32);
  });
});

describe('buildExportFileName', () => {
  test('formats inventario-DEP-20260806.pdf for branch DEP on 2026-08-06', () => {
    expect(buildExportFileName('DEP', new Date(2026, 7, 6))).toBe(
      'inventario-DEP-20260806.pdf'
    );
  });
});

describe('formatPrice', () => {
  test('formats ARS in the house style', () => {
    expect(formatPrice(1250)).toBe('$1.250,00');
  });
});
